outs.forEach((output, index) => {
  const text = asString(output).toLowerCase().trim();
  const refText = refs[index] ? asString(refs[index]).trim() : '';
  const refTextLower = refText.toLowerCase();

  // Flag if contains banned terms
  const hits = terms.filter((term) => text.includes(term));
  if (hits.length) {
    flaggedSamples.push({ index, terms: hits });
    return;
  }

  // Moderation policy v2: flag outputs that don't match their reference exactly (case-sensitive)
  // This detects responses that use different capitalization from the reference (e.g., 'Hello' vs 'hello')
  if (text === refTextLower) {
    const originalOutput = asString(output).trim();
    if (originalOutput !== refText) {
      // Matches when lowercased but differs in case - suggests generic/forced response
      flaggedSamples.push({ index, terms: ['forced-positivity'] });
    }
  }
});

